	private bool handleSingleClick(GTreeNode clickedNode) {
		if (clickedNode is FSBFileNode fileNode) {
			foreach (FSBFileHandler handler in fileHandlers) {
				if (handler.fileFocused(fileNode)) {
					return true;
				}
			}
		}
		return false;
	}

	private bool handleDoubleClick(GTreeNode clickedNode) {
		if (clickedNode is FSBFileNode fileNode) {
			foreach (FSBFileHandler handler in fileHandlers) {
				if (handler.fileDefaultAction(fileNode)) {
					return true;
				}
			}
		}
		return false;
	}

