	/* @Override */
	public FSBActionContext getActionContext(MouseEvent @event) {
		return new FSBActionContext(this, getSelectedNodes(@event), @event, gTree);
	}

	private List<FSBNode> getSelectedNodes(MouseEvent @event) {
		TreePath[] selectionPaths = gTree.getSelectionPaths();
		List<FSBNode> list = new(selectionPaths.length);
		foreach (TreePath selectionPath in selectionPaths) {
			object lastPathComponent = selectionPath.getLastPathComponent();
			if (lastPathComponent is FSBNode fsbNode) {
				list.add(fsbNode);
			}
		}
		if (list.isEmpty() && @event != null) {
			object source = @event.getSource();
			if (source is JTree sourceTree && gTree.isMyJTree(sourceTree)) {
				int x = @event.getX();
				int y = @event.getY();
				GTreeNode nodeAtEventLocation = gTree.getNodeForLocation(x, y);
				if (nodeAtEventLocation != null && nodeAtEventLocation is FSBNode fsbNode) {
					list.add(fsbNode);
				}
			}
		}
		return list;
	}

